# ============================================================
# EMBEDDED STANDALONE ASSETS (ZERO EXTERNAL FILE DEPENDENCIES)
# ============================================================
EMBEDDED_LOGO_B64 = """"""
EMBEDDED_IMAGE_B64 = ""
EMBEDDED_HTML_ZLIB_B64 = ""
EMBEDDED_CHART_ZLIB_B64 = ""

def ensure_standalone_assets():
    """Extracts embedded assets if not already present on disk."""
    dir_path = os.path.dirname(os.path.abspath(__file__))
    logo_file = os.path.join(dir_path, "logo.png")
    if not os.path.exists(logo_file):
        try:
            with open(logo_file, "wb") as f:
                f.write(base64.b64decode(EMBEDDED_LOGO_B64))
        except Exception:
            pass

    image_file = os.path.join(dir_path, "image.png")
    if not os.path.exists(image_file):
        try:
            with open(image_file, "wb") as f:
                f.write(base64.b64decode(EMBEDDED_IMAGE_B64))
        except Exception:
            pass

    watermark_file = os.path.join(dir_path, "watermark.png")
    if not os.path.exists(watermark_file) and os.path.exists(logo_file):
        try:
            from PIL import Image
            img = Image.open(logo_file).convert("RGBA")
            r, g, b, a = img.split()
            a = a.point(lambda p: int(p * 0.08))
            wm = Image.merge("RGBA", (r, g, b, a))
            wm.save(watermark_file, "PNG")
        except Exception:
            pass

    chart_file = os.path.join(dir_path, "chart.umd.min.js")
    if not os.path.exists(chart_file):
        try:
            raw_chart = zlib.decompress(base64.b64decode(EMBEDDED_CHART_ZLIB_B64)).decode("utf-8")
            with open(chart_file, "w", encoding="utf-8") as f:
                f.write(raw_chart)
        except Exception:
            pass

    html_file = os.path.join(dir_path, "index.html")
    combined_file = os.path.join(dir_path, "VoltRoof_Combined.html")
    if not os.path.exists(html_file) or not os.path.exists(combined_file):
        try:
            raw_html = zlib.decompress(base64.b64decode(EMBEDDED_HTML_ZLIB_B64)).decode("utf-8")
            if not os.path.exists(html_file):
                with open(html_file, "w", encoding="utf-8") as f:
                    f.write(raw_html)
            if not os.path.exists(combined_file):
                with open(combined_file, "w", encoding="utf-8") as f:
                    f.write(raw_html)
        except Exception:
            pass

# Ensure assets are present at module load
ensure_standalone_assets()

