def handle_api_calculate(data: dict) -> dict:
    mode = data.get("mode", "roof")
    customer_name = data.get("customer_name", "Solar Site")
    location = data.get("location", "Karnataka")
    email = data.get("email", "")
    contact_number = str(data.get("contact_number", "")).strip()
    sanctioned_load_kw = safe_float(data.get("sanctioned_load_kw")) if data.get("sanctioned_load_kw") else None
    custom_tariff = safe_float(data.get("custom_tariff", 8.05), 8.05)
    sites_data = data.get("sites")

    if sites_data and len(sites_data) > 0:
        rep = build_multi_site_report(
            sites_data=sites_data,
            project_name=customer_name,
            location=location,
            email=email,
            custom_tariff=custom_tariff,
            contact_number=contact_number,
            sanctioned_load_kw=sanctioned_load_kw,
        )
    else:
        L = safe_float(data.get("length_ft", 40.0), 40.0)
        B = safe_float(data.get("breadth_ft", 30.0), 30.0)
        parapet_ft = safe_float(data.get("parapet_ft", 1.5), 1.5)
        monthly_units = safe_float(data.get("monthly_units", 1200.0), 1200.0)
        distance_m = safe_float(data.get("distance_m", 20.0), 20.0)
        panel_watt = safe_int(data.get("panel_watt", 550), 550)
        panel_tech = str(data.get("panel_tech", "Mono-PERC (Mono-facial)"))
        buildings = [("Building 1", L, B)]
        rep = build_system_report(
            mode=mode,
            buildings=buildings,
            parapet_ft=parapet_ft,
            monthly_units=monthly_units,
            distance_m=distance_m,
            panel_watt=panel_watt,
            customer_name=customer_name,
            location=location,
            email=email,
            panel_tech=panel_tech,
            contact_number=contact_number,
            sanctioned_load_kw=sanctioned_load_kw,
        )

    # 12-item plant BOM
    bom_items = []
    for item in rep.bom_items:
        bom_items.append({
            "sl": item.sl_no,
            "desc": item.description,
            "spec": item.specification,
            "qty": item.quantity,
            "amt": round(item.amount_inr, 2)
        })

    # ESCOM items
    escom_specs = {
        "registration": ("Application & Registration Fee", "Online portal fee (+18% GST)", False),
        "facilitation": ("Facilitation & Processing Fee", "Field inspection (+18% GST)", False),
        "ppa_esign": ("PPA e-Sign Charge", "Statutory agreement stamping", False),
        "meter_estimate": ("Bi-Directional Net Meter", "Meter testing & approval", False),
        "security_deposit": ("Refundable Security Deposit", "LT connectivity deposit", True),
    }
    escom_list = []
    sl_i = 1
    for k, amt in rep.escom_budget.items():
        name, spec, is_ref = escom_specs.get(k, (k.replace('_', ' ').title(), "Statutory utility procedure", False))
        escom_list.append({
            "sl": sl_i,
            "name": name,
            "spec": spec,
            "amt": round(amt, 2),
            "note": "Refundable" if is_ref else "+ 18% GST"
        })
        sl_i += 1

    # Amortization schedule (25 years)
    amort_list = []
    cur_g = rep.annual_generation_kwh
    cum_net = 0.0
    scale = (custom_tariff / TARIFF_25Y[0]) if custom_tariff > 0 else 1.0
    amc_y = rep.total_capacity_kw * 600.0

    for y_idx in range(25):
        base_t = TARIFF_25Y[y_idx if y_idx < len(TARIFF_25Y) else -1]
        t_val = round(base_t * scale, 2)
        rev = cur_g * t_val
        net_val = rev - amc_y
        cum_net += net_val
        amort_list.append({
            "year": y_idx + 1,
            "gen": round(cur_g),
            "tariff": f"{t_val:.2f}",
            "revenue": round(rev),
            "amc": round(amc_y),
            "net": round(net_val),
            "cum": round(cum_net)
        })
        cur_g *= 0.99

    res = {
        "schemaVersion": 1,
        "calculated_at": datetime.datetime.now().isoformat(),
        "customer_name": rep.customer_name,
        "location": rep.location,
        "mode": rep.mode,
        "capacityKw": round(rep.total_capacity_kw, 2),
        "installedDckWp": round((rep.total_panels * rep.panel_watt) / 1000.0, 2),
        "rawCapacityKw": round(rep.total_capacity_kw, 2),
        "isCapped20kW": rep.total_capacity_kw >= 20.0 or (sanctioned_load_kw is not None and sanctioned_load_kw >= 20.0),
        "kercNotice": "20 kW Reached For LT Limited 20kW as per KERC/ESCOM Regulations" if (rep.total_capacity_kw >= 20.0 or (sanctioned_load_kw is not None and sanctioned_load_kw >= 20.0)) else "",
        "roofAreaStatus": rep.roof_area_status,
        "panels": rep.total_panels,
        "strings": max(1, math.ceil(rep.total_panels / 20.0)),
        "invKw": round(rep.ac_calculated_kw, 2),
        "phase3": rep.ac_calculated_kw > 5.0,
        "deratedAcKw": round(rep.ac_calculated_kw, 2),
        "invCable": {
            "cable": rep.acdb_grid_cable,
            "isolator": f"{int(rep.acdb_current_a)}A MCB",
            "current": rep.acdb_current_a
        },
        "acdb": {
            "breakerRating": int(rep.acdb_current_a),
            "ratedCurrent": rep.acdb_rated_current_a,
            "gridCable": rep.acdb_grid_cable,
            "busbar": rep.acdb_busbar,
            "components": [[c[0], c[1]] for c in rep.acdb_components] if rep.acdb_components else []
        },
        "bom": {
            "items": bom_items,
            "plantTotal": round(rep.bom_plant_total_inr, 2),
            "escom": escom_list,
            "escomTotal": round(rep.total_escom_budget_inr, 2),
            "totalCapitalOutlay": round(rep.grand_total_capital_inr, 2)
        },
        "monthly": rep.monthly_generation_kwh,
        "annual": round(rep.annual_generation_kwh, 2),
        "series25": [round(rep.annual_generation_kwh * (0.99 ** y), 2) for y in range(25)],
        "total25": round(rep.total_generation_25y_kwh, 2),
        "pr": rep.performance_ratio_pr,
        "cuf": rep.capacity_utilization_factor_cuf,
        "sysEff": rep.system_efficiency_pct,
        "specificYield": rep.specific_energy_yield_kwh_per_kw,
        "amort": amort_list,
        "payY": rep.payback_years,
        "payM": rep.payback_months,
        "lifetimeProfit": rep.post_payback_profit_inr,
        "fd25y": rep.fd_25y_inr,
        "co2": rep.carbon_emission_reduction_tonnes_25y,
        "trees": rep.trees_planted_25y,
        "carKm": int((rep.carbon_emission_reduction_tonnes_25y * 1000) / 0.12),
        "coalT": round(rep.total_generation_25y_kwh * 0.0004, 1),
        "sitesCount": len(rep.site_reports) if rep.site_reports else 1
    }
    return res


class SolarAppRequestHandler(SimpleHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        directory = os.path.dirname(os.path.abspath(__file__))
        super().__init__(*args, directory=directory, **kwargs)

    def do_GET(self):
        parsed = urlparse(self.path)
        cur_dir = os.path.dirname(os.path.abspath(__file__))

        # Serve static uploads
        if parsed.path.startswith("/uploads/"):
            rel_path = parsed.path.replace("/uploads/", "", 1).lstrip("/").replace("/", os.sep)
            file_path = os.path.abspath(os.path.join(cur_dir, "data", "uploads", rel_path))
            uploads_dir = os.path.abspath(os.path.join(cur_dir, "data", "uploads"))
            if not file_path.startswith(uploads_dir):
                self.send_response(403)
                self.end_headers()
                return
            if os.path.exists(file_path) and os.path.isfile(file_path):
                ext = os.path.splitext(file_path)[1].lower()
                mime_map = {
                    ".png": "image/png",
                    ".jpg": "image/jpeg",
                    ".jpeg": "image/jpeg",
                    ".webp": "image/webp",
                    ".svg": "image/svg+xml",
                    ".gif": "image/gif",
                    ".pdf": "application/pdf",
                    ".csv": "text/csv",
                    ".json": "application/json",
                    ".txt": "text/plain",
                }
                ctype = mime_map.get(ext, "application/octet-stream")
                try:
                    with open(file_path, "rb") as f:
                        file_bytes = f.read()
                    self.send_response(200)
                    self.send_header("Content-Type", ctype)
                    self.send_header("Content-Length", str(len(file_bytes)))
                    self.send_header("Cache-Control", "public, max-age=86400")
                    self.end_headers()
                    self.wfile.write(file_bytes)
                    return
                except Exception as e:
                    self.send_response(500)
                    self.end_headers()
                    return
            else:
                self.send_response(404)
                self.end_headers()
                return

        # Serve User Manual PDF
        if parsed.path in ("/user_manual.pdf", "/api/user_manual", "/api/user_manual/download"):
            manual_file = os.path.join(cur_dir, "user_manual.pdf")
            if os.path.exists(manual_file):
                try:
                    with open(manual_file, "rb") as f:
                        pdf_bytes = f.read()
                    self.send_response(200)
                    self.send_header("Content-Type", "application/pdf")
                    self.send_header("Content-Disposition", 'inline; filename="VoltRoof_User_Manual.pdf"')
                    self.send_header("Content-Length", str(len(pdf_bytes)))
                    self.end_headers()
                    self.wfile.write(pdf_bytes)
                    return
                except Exception as e:
                    self.send_response(500)
                    self.send_header("Content-Type", "application/json")
                    self.end_headers()
                    self.wfile.write(json.dumps({"error": str(e)}).encode())
                    return
            else:
                self.send_response(404)
                self.send_header("Content-Type", "application/json")
                self.end_headers()
                self.wfile.write(json.dumps({"error": "User manual document not found"}).encode())
                return

        # Return User Manual Metadata
        elif parsed.path == "/api/user_manual_meta":
            manual_file = os.path.join(cur_dir, "user_manual.pdf")
            meta_file = os.path.join(cur_dir, "user_manual_meta.json")
            meta = {}
            if os.path.exists(meta_file):
                try:
                    with open(meta_file, "r", encoding="utf-8") as mf:
                        meta = json.load(mf)
                except Exception:
                    pass
            if not meta and os.path.exists(manual_file):
                st = os.stat(manual_file)
                meta = {
                    "exists": True,
                    "filename": "VoltRoof_User_Manual.pdf",
                    "size_bytes": st.st_size,
                    "updated_at": datetime.datetime.fromtimestamp(st.st_mtime).strftime("%d-%b-%Y %H:%M"),
                    "updated_by": "Administrator"
                }
            elif not meta:
                meta = {"exists": False, "filename": "", "size_bytes": 0, "updated_at": "", "updated_by": ""}
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(meta).encode())
            return

        # Return Current Pricing Configuration
        elif parsed.path == "/api/pricing":
            cur_pricing = db_load_json(PRICING_DB_FILE, DEFAULT_PRICING_MAP)
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(cur_pricing).encode())
            return

        # Return Visitor Analytics Stats
        elif parsed.path == "/api/visitors/stats":
            visitors = db_load_json(VISITORS_DB_FILE, [])
            total_visits = len(visitors)
            unique_sessions = len(set(v.get("session_id", "") for v in visitors if v.get("session_id")))
            today_str = datetime.datetime.now().strftime("%Y-%m-%d")
            today_visits = len([v for v in visitors if str(v.get("timestamp", "")).startswith(today_str)])
            recent_visitors = visitors[-30:][::-1]
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps({
                "total_visits": total_visits,
                "unique_sessions": unique_sessions,
                "today_visits": today_visits,
                "recent": recent_visitors
            }).encode())
            return

        # Return Feedback Submissions & Statistics
        elif parsed.path == "/api/feedback":
            fb_stats = backend_ext.get_feedback_detailed()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(fb_stats).encode())
            return

        # Return Admin List (Sanitized: username, role, status, created_at)
        # --- Enhanced Backend Extensions (GET) ---
        elif parsed.path == "/api/tickets":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(backend_ext.get_tickets()).encode())
            return

        elif parsed.path in ("/api/visitors", "/api/visitors/detailed"):
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(backend_ext.get_visitors_detailed()).encode())
            return

        elif parsed.path in ("/api/pricing/categories", "/api/pricing/catalog"):
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(backend_ext.get_pricing_catalog()).encode())
            return

        elif parsed.path == "/api/policies":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(backend_ext.get_policies()).encode())
            return

        elif parsed.path in ("/api/content/slides", "/api/content/slides/current"):
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(backend_ext.get_content_slides()).encode())
            return

        elif parsed.path == "/api/upload/list":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(backend_ext.get_uploads_list()).encode())
            return

        elif parsed.path == "/api/admin/hierarchy":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(backend_ext.get_hierarchy()).encode())
            return

        elif parsed.path == "/api/email_logs":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(backend_ext.load_json("email_logs.json", [])).encode())
            return

        elif parsed.path == "/api/admin/list":
            admins_list = db_load_json(ADMINS_DB_FILE, INITIAL_ADMINS)
            safe_admins = []
            for a in admins_list:
                safe_admins.append({
                    "username": a.get("username", "Admin"),
                    "role": a.get("role", "admin"),
                    "status": a.get("status", "approved"),
                    "created_at": a.get("created_at", "")
                })
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(safe_admins).encode())
            return

        if parsed.path in ("/", "", "/admin", "/admin/login", "/admin_login", "/login/admin", "/portal"):
            if os.path.exists(os.path.join(cur_dir, "VoltRoof_Combined.html")):
                self.path = "/VoltRoof_Combined.html"
            elif os.path.exists(os.path.join(cur_dir, "index.html")):
                self.path = "/index.html"
            elif os.path.exists(os.path.join(cur_dir, "voltroof_solar_pv_estimator_standalone.html")):
                self.path = "/voltroof_solar_pv_estimator_standalone.html"
            elif os.path.exists(os.path.join(cur_dir, "voltroof_solar_pv_estimator.html")):
                self.path = "/voltroof_solar_pv_estimator.html"
            else:
                self.path = "/index.html"
        return super().do_GET()

    def do_POST(self):
        parsed = urlparse(self.path)
        content_len = int(self.headers.get("Content-Length", 0))
        post_body = self.rfile.read(content_len).decode("utf-8")
        data = json.loads(post_body) if post_body else {}

        if parsed.path == "/api/calculate":
            try:
                result_dto = handle_api_calculate(data)
                self.send_response(200)
                self.send_header("Content-Type", "application/json")
                self.end_headers()
                self.wfile.write(json.dumps(result_dto).encode())
                return
            except Exception as e:
                self.send_response(500)
                self.send_header("Content-Type", "application/json")
                self.end_headers()
                self.wfile.write(json.dumps({"success": False, "error": str(e)}).encode())
                return

        elif parsed.path == "/api/download_pdf":
            try:
                mode = data.get("mode", "roof")
                customer_name = data.get("customer_name", "Solar Site")
                location = data.get("location", "Karnataka")
                email = data.get("email", "")
                contact_number = str(data.get("contact_number", "")).strip()
                sanctioned_load_kw = safe_float(data.get("sanctioned_load_kw")) if data.get("sanctioned_load_kw") else None
                custom_tariff = safe_float(data.get("custom_tariff", 8.05), 8.05)
                sites_data = data.get("sites")

                if sites_data and len(sites_data) > 0:
                    report = build_multi_site_report(
                        sites_data=sites_data,
                        project_name=customer_name,
                        location=location,
                        email=email,
                        custom_tariff=custom_tariff,
                        contact_number=contact_number,
                        sanctioned_load_kw=sanctioned_load_kw,
                    )
                else:
                    L = safe_float(data.get("length_ft", 40.0), 40.0)
                    B = safe_float(data.get("breadth_ft", 30.0), 30.0)
                    parapet_ft = safe_float(data.get("parapet_ft", 1.5), 1.5)
                    monthly_units = safe_float(data.get("monthly_units", 1200.0), 1200.0)
                    distance_m = safe_float(data.get("distance_m", 20.0), 20.0)
                    panel_watt = safe_int(data.get("panel_watt", 550), 550)
                    panel_tech = str(data.get("panel_tech", "Mono-PERC (Mono-facial)"))

                    buildings = [("Building 1", L, B)]
                    report = build_system_report(
                        mode=mode,
                        buildings=buildings,
                        parapet_ft=parapet_ft,
                        monthly_units=monthly_units,
                        distance_m=distance_m,
                        panel_watt=panel_watt,
                        customer_name=customer_name,
                        location=location,
                        email=email,
                        panel_tech=panel_tech,
                        contact_number=contact_number,
                        sanctioned_load_kw=sanctioned_load_kw,
                    )

                script_dir = os.path.dirname(os.path.abspath(__file__))
                pdf_file = os.path.join(script_dir, "LT_RTSPV_Report.pdf")
                export_pdf(report, pdf_file)

                with open(pdf_file, "rb") as f:
                    pdf_bytes = f.read()

                self.send_response(200)
                self.send_header("Content-Type", "application/pdf")
                self.send_header("Content-Disposition", 'attachment; filename="LT_RTSPV_Report.pdf"')
                self.send_header("Content-Length", str(len(pdf_bytes)))
                self.end_headers()
                self.wfile.write(pdf_bytes)
                return
            except Exception as e:
                self.send_response(500)
                self.send_header("Content-Type", "application/json")
                self.end_headers()
                self.wfile.write(json.dumps({"error": str(e)}).encode())
                return

